<?php
require_once dirname(__DIR__).'/classes/WatchysStockObjectGuard.php';
function objectGuardCheck($v,$m){if(!$v){throw new RuntimeException($m);}}
function objectGuardDeny($f){$caught=false;try{$f();}catch(RuntimeException|InvalidArgumentException $e){$caught=true;}objectGuardCheck($caught,'Refus attendu absent.');}
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$db->exec('CREATE TABLE g_stock_available(id_stock_available INT PRIMARY KEY,id_product INT,id_product_attribute INT,id_shop INT,id_shop_group INT,quantity INT,depends_on_stock INT)');$db->exec('INSERT INTO g_stock_available VALUES(1,7736,0,1,0,10,0)');
$load=static function()use($db){$r=$db->query('SELECT * FROM g_stock_available')->fetch(PDO::FETCH_ASSOC);$r['id']=$r['id_stock_available'];unset($r['id_stock_available']);return (object)$r;};
$obj=$load();$guard=new WatchysStockObjectGuard($db,'g_',$obj);$obj->quantity=9;objectGuardDeny(static function()use($guard){$guard->update(static function(){return true;});});
$db->beginTransaction();$db->exec('UPDATE g_stock_available SET quantity=8');$called=false;objectGuardDeny(static function()use($guard,&$called){$guard->update(static function()use(&$called){$called=true;return true;});});objectGuardCheck(!$called&&(int)$db->query('SELECT quantity FROM g_stock_available')->fetchColumn()===8,'Objet périmé a été écrit.');
$obj=$load();$guard=new WatchysStockObjectGuard($db,'g_',$obj);$obj->quantity=7;$write=static function()use($db,$obj){$s=$db->prepare('UPDATE g_stock_available SET quantity=? WHERE id_stock_available=?');$s->execute([$obj->quantity,$obj->id]);return true;};$guard->update($write);objectGuardCheck((int)$db->query('SELECT quantity FROM g_stock_available')->fetchColumn()===7,'Écriture valide non exécutée.');
$obj->quantity=6;objectGuardDeny(static function()use($guard,$db){$guard->update(static function()use($db){$db->exec('UPDATE g_stock_available SET quantity=6');return false;});});objectGuardCheck((int)$db->query('SELECT quantity FROM g_stock_available')->fetchColumn()===7&&$db->inTransaction(),'Écriture native false non annulée.');
$obj->quantity=-1;objectGuardDeny(static function()use($guard,$write){$guard->update($write);});$obj->quantity=6;$obj->id_product=8188;objectGuardDeny(static function()use($guard,$write){$guard->update($write);});objectGuardCheck((int)$db->query('SELECT quantity FROM g_stock_available')->fetchColumn()===7,'Identité/quantité invalide a modifié le stock.');
$db->rollBack();objectGuardCheck((int)$db->query('SELECT quantity FROM g_stock_available')->fetchColumn()===10,'Rollback appelant non respecté.');
echo "SUCCÈS — Garde objet SQL : snapshot périmé refusé avant callback, écriture fraîche relue, échec natif annulé, identité/quantité contrôlées et rollback appelant. SQLite ; pas de classe native chargée.\n";
